using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, int> _index = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    private string[] _codes = new string[16];
    private string[] _categories = new string[16];
    private double[] _prices = new double[16];
    private int _count;

    public void AddProduct(string code, string category, decimal price)
    {
        if (_index.TryGetValue(code, out int idx))
        {
            var oldCategory = _categories[idx];
            _categories[idx] = category;
            _prices[idx] = (double)price;

            if (!oldCategory.Equals(category, StringComparison.OrdinalIgnoreCase))
            {
                if (_categoryIndex.TryGetValue(oldCategory, out var oldList))
                    oldList.Remove(code);
                AddToCategoryIndex(category, code);
            }
            return;
        }

        idx = _count++;
        EnsureCapacity(idx);

        _codes[idx] = code;
        _categories[idx] = category;
        _prices[idx] = (double)price;
        _index[code] = idx;

        AddToCategoryIndex(category, code);
    }

    public string? GetCategory(string code)
        => _index.TryGetValue(code, out int idx) ? _categories[idx] : null;

    /// <summary>
    /// Computes total price using SIMD-vectorized summation over a contiguous price array.
    /// </summary>
    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        // Resolve codes to indices, then SIMD-sum the corresponding prices
        Span<double> resolved = _count <= 1024
            ? stackalloc double[Math.Min(_count, 1024)]
            : new double[_count];

        int resolvedCount = 0;
        foreach (var code in codes)
        {
            if (_index.TryGetValue(code, out int idx))
                resolved[resolvedCount++] = _prices[idx];
        }

        double total = SumVectorized(resolved[..resolvedCount]);
        return (decimal)total;
    }

    /// <summary>
    /// Returns products by category using a pre-built reverse index (O(1) lookup).
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_categoryIndex.TryGetValue(category, out var list))
            return new List<string>(list);
        return new List<string>();
    }

    private static double SumVectorized(ReadOnlySpan<double> values)
    {
        double sum = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<double>.Count)
        {
            var vSum = Vector<double>.Zero;
            int vectorEnd = values.Length - values.Length % Vector<double>.Count;

            ReadOnlySpan<double> vectorizable = values[..vectorEnd];
            ref double searchSpace = ref MemoryMarshal.GetReference(vectorizable);

            for (int i = 0; i < vectorEnd; i += Vector<double>.Count)
            {
                var v = new Vector<double>(values[i..]);
                vSum += v;
            }

            sum = Vector.Sum(vSum);

            // Handle remainder
            for (int i = vectorEnd; i < values.Length; i++)
                sum += values[i];
        }
        else
        {
            for (int i = 0; i < values.Length; i++)
                sum += values[i];
        }

        return sum;
    }

    private void AddToCategoryIndex(string category, string code)
    {
        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _categoryIndex, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);
    }

    private void EnsureCapacity(int index)
    {
        if (index < _codes.Length) return;
        int newSize = _codes.Length * 2;
        Array.Resize(ref _codes, newSize);
        Array.Resize(ref _categories, newSize);
        Array.Resize(ref _prices, newSize);
    }
}

